<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { adminPaymentsApi, type PaymentResource, type PaymentPage } from '../services/adminPayments'
import { ApiRequestError } from '../services/apiError'
import StatusNotice from '../components/StatusNotice.vue'
const props = defineProps<{ mode: 'payments' | 'reconciliation' }>()
const tab = ref<'payments'|'callbacks'|'exceptions'>(props.mode === 'payments' ? 'payments' : 'exceptions')
const result = ref<PaymentPage>(); const loading = ref(true); const error = ref(''); const keyword = ref(''); const status = ref(''); const selected = ref<PaymentResource>(); const reason = ref(''); const resolution = ref(''); const reconcileText = ref(''); const actionMessage = ref(''); const working = ref(false)
const items = computed(() => result.value?.items ?? []); const title = computed(() => props.mode === 'payments' ? '支付交易' : '支付对账')
const labels: Record<string,string> = { CREATED:'待支付', PROCESSING:'处理中', SUCCESS:'已支付', PAID:'已支付', FAILED:'失败', UNKNOWN:'待确认', RECONCILED:'已对账', EXCEPTION:'异常' }
function label(value: string) { return labels[value] || value }
function money(item: PaymentResource) { return `${(item.amountCent / 100).toFixed(2)} ${item.currency}` }
async function load() { loading.value = true; error.value = ''; try { result.value = tab.value === 'payments' ? await adminPaymentsApi.payments({ keyword: keyword.value || undefined, status: status.value || undefined }) : tab.value === 'callbacks' ? await adminPaymentsApi.callbacks({ keyword: keyword.value || undefined, status: status.value || undefined }) : await adminPaymentsApi.exceptions({ keyword: keyword.value || undefined, status: status.value || undefined }) } catch (caught) { error.value = caught instanceof ApiRequestError ? caught.message : '数据暂时无法加载' } finally { loading.value = false } }
async function action(kind: 'query'|'resolve') { if (!selected.value) return; working.value = true; actionMessage.value = ''; try { if (kind === 'query') await adminPaymentsApi.queryPayment(selected.value.id, { reason: reason.value || '后台主动查单', expectedVersion: selected.value.version }); else await adminPaymentsApi.resolve(selected.value.id, { resolution: resolution.value, reason: reason.value, expectedVersion: selected.value.version }); actionMessage.value = kind === 'query' ? '主动查单已提交' : '异常账务已处理'; selected.value = undefined; await load() } catch (caught) { actionMessage.value = caught instanceof Error ? caught.message : '操作失败' } finally { working.value = false } }
async function reconcile() { working.value = true; try { await adminPaymentsApi.reconcile({ parameters: reconcileText.value || undefined, dryRun: false }); actionMessage.value = '对账任务已提交'; await load() } catch (caught) { actionMessage.value = caught instanceof Error ? caught.message : '对账失败' } finally { working.value = false } }
onMounted(load)
</script>
<template><article class="page payment-admin-page"><header class="page-heading"><div><div class="eyebrow">资金运营</div><h1>{{ title }}</h1><p>支付状态、渠道回调、异常账务与对账均来自服务端权威数据。</p></div><button class="ghost-button" :disabled="loading" @click="load">刷新</button></header><StatusNotice v-if="error" tone="danger" title="数据加载失败" :detail="error"/><StatusNotice v-if="actionMessage" tone="warning" title="操作结果" :detail="actionMessage"/><section class="payment-admin-tabs"><button v-for="item in (['payments','callbacks','exceptions'] as const)" :key="item" :class="{active: tab === item}" @click="tab = item; load()">{{ item === 'payments' ? '支付交易' : item === 'callbacks' ? '回调日志' : '异常账务' }}</button></section><form class="card payment-admin-filters" @submit.prevent="load"><label class="field"><span class="field-label">关键词</span><input v-model="keyword" class="input" maxlength="100" placeholder="订单号或网关交易号"/></label><label class="field"><span class="field-label">状态</span><input v-model="status" class="input" maxlength="64" placeholder="按状态筛选"/></label><button class="primary-button" :disabled="loading">查询</button></form><section v-if="props.mode === 'reconciliation'" class="card reconciliation-box"><div><h2>执行对账</h2><p>对账结果由服务端写入对账记录，重复提交使用幂等请求。</p></div><input v-model="reconcileText" class="input" maxlength="2000" placeholder="对账参数（可选）"/><button class="primary-button" :disabled="working" @click="reconcile">执行对账</button></section><section v-if="loading" class="card skeleton-stack"><div v-for="n in 6" :key="n" class="skeleton payment-row-skeleton"/></section><section v-else-if="!items.length" class="card empty-state"><h2>暂无数据</h2><p>当前筛选条件没有可展示的记录。</p></section><section v-else class="card payment-table-card"><div class="payment-table-wrap"><table class="payment-table"><thead><tr><th>订单号</th><th>网关</th><th>网关交易号</th><th>状态</th><th>金额</th><th>支付时间</th><th>对账状态</th><th>操作</th></tr></thead><tbody><tr v-for="item in items" :key="item.id"><td>{{ item.orderNo }}</td><td>{{ item.gateway }}</td><td>{{ item.gatewayTradeNo || '暂无' }}</td><td><span class="status-chip" :data-status="item.status">{{ label(item.status) }}</span></td><td>{{ money(item) }}</td><td>{{ item.paidAt ? new Date(item.paidAt).toLocaleString('zh-CN') : '暂无' }}</td><td>{{ item.reconciliationStatus || '待处理' }}</td><td><button class="secondary-button" @click="selected = item">{{ tab === 'exceptions' ? '处理异常' : '主动查单' }}</button></td></tr></tbody></table></div></section><div v-if="selected" class="modal-backdrop" @click.self="selected = undefined"><section class="modal" role="dialog" aria-modal="true"><header class="modal-header"><div><h2>{{ tab === 'exceptions' ? '处理异常账务' : '主动查单' }}</h2><p>目标：{{ selected.orderNo }}；服务端版本：{{ selected.version }}</p></div><button class="icon-button" @click="selected = undefined">×</button></header><label class="field"><span class="field-label">原因</span><textarea v-model="reason" class="input" maxlength="2000" placeholder="填写本次操作原因"/></label><label v-if="tab === 'exceptions'" class="field"><span class="field-label">处理结果</span><textarea v-model="resolution" class="input" maxlength="2000" placeholder="填写异常处理结果"/></label><footer class="modal-footer"><button class="ghost-button" @click="selected = undefined">取消</button><button class="primary-button" :disabled="working || (tab === 'exceptions' && (!reason || !resolution))" @click="action(tab === 'exceptions' ? 'resolve' : 'query')">{{ working ? '提交中…' : '确认提交' }}</button></footer></section></div></article></template>
